import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Conv2d: in_channels=3, out_channels=96, kernel=11x11, stride=4, padding=2
// One fused kernel computes the whole convolution (including bias).
// Each block handles one (batch, out_channel) pair and a TILE x TILE output tile.
// The required input patch (with halo) and the filter weights are staged in
// shared memory and reused by all threads in the block.

#define TILE 8
#define KSIZE 11
#define STRIDE 4
#define PAD 2
#define CIN 3
#define PATCH ((TILE - 1) * STRIDE + KSIZE)  // 39

__global__ void conv2d_fwd_kernel(
    const float* __restrict__ input,   // N x CIN x H x W
    const float* __restrict__ weight,  // OC x CIN x K x K
    const float* __restrict__ bias,    // OC
    float* __restrict__ output,        // N x OC x OH x OW
    int N, int H, int W, int OH, int OW, int OC)
{
    __shared__ float s_in[CIN][PATCH][PATCH + 1];
    __shared__ float s_w[CIN][KSIZE][KSIZE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * TILE + tx;
    const int nthreads = TILE * TILE;

    const int ow0 = blockIdx.x * TILE;
    const int oh0 = blockIdx.y * TILE;
    const int bz  = blockIdx.z;
    const int oc  = bz % OC;
    const int n   = bz / OC;

    // Stage the filter weights for this output channel in shared memory.
    for (int i = tid; i < CIN * KSIZE * KSIZE; i += nthreads) {
        int c   = i / (KSIZE * KSIZE);
        int r   = (i / KSIZE) % KSIZE;
        int col = i % KSIZE;
        s_w[c][r][col] = weight[((oc * CIN + c) * KSIZE + r) * KSIZE + col];
    }

    // Top-left corner (in input coords) of the patch needed by this tile.
    const int in_h0 = oh0 * STRIDE - PAD;
    const int in_w0 = ow0 * STRIDE - PAD;

    // Stage the input patch (with halo + zero padding) in shared memory.
    for (int i = tid; i < CIN * PATCH * PATCH; i += nthreads) {
        int c   = i / (PATCH * PATCH);
        int r   = (i / PATCH) % PATCH;
        int col = i % PATCH;
        int ih  = in_h0 + r;
        int iw  = in_w0 + col;
        float v = 0.0f;
        if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
            v = input[((n * CIN + c) * H + ih) * W + iw];
        }
        s_in[c][r][col] = v;
    }
    __syncthreads();

    const int oh = oh0 + ty;
    const int ow = ow0 + tx;
    if (oh < OH && ow < OW) {
        float acc = 0.0f;
        const int bh = ty * STRIDE;
        const int bw = tx * STRIDE;
        #pragma unroll
        for (int c = 0; c < CIN; ++c) {
            #pragma unroll
            for (int kh = 0; kh < KSIZE; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < KSIZE; ++kw) {
                    acc += s_in[c][bh + kh][bw + kw] * s_w[c][kh][kw];
                }
            }
        }
        acc += bias[oc];
        output[((n * OC + oc) * OH + oh) * OW + ow] = acc;
    }
}

torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(),
                "conv2d_forward: all tensors must be CUDA");
    TORCH_CHECK(input.dim() == 4, "conv2d_forward: input must be 4D (N,C,H,W)");
    TORCH_CHECK(input.size(1) == CIN, "conv2d_forward: expected 3 input channels");
    TORCH_CHECK(weight.size(1) == CIN && weight.size(2) == KSIZE && weight.size(3) == KSIZE,
                "conv2d_forward: expected weight shape (OC,3,11,11)");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "conv2d_forward: float32 only");

    auto x = input.contiguous();
    auto w = weight.contiguous();
    auto b = bias.contiguous();

    const int N  = x.size(0);
    const int H  = x.size(2);
    const int W  = x.size(3);
    const int OC = w.size(0);
    const int OH = (H + 2 * PAD - KSIZE) / STRIDE + 1;
    const int OW = (W + 2 * PAD - KSIZE) / STRIDE + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "conv2d_forward: invalid output size");
    TORCH_CHECK((long)N * OC <= 65535, "conv2d_forward: N*OC exceeds grid.z limit");

    auto out = torch::empty({N, OC, OH, OW}, x.options());

    dim3 block(TILE, TILE);
    dim3 grid((OW + TILE - 1) / TILE, (OH + TILE - 1) / TILE, N * OC);

    conv2d_fwd_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        x.data_ptr<float>(), w.data_ptr<float>(), b.data_ptr<float>(),
        out.data_ptr<float>(), N, H, W, OH, OW, OC);

    return out;
}
"""

cpp_src = "torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias);"

_conv_mod = load_inline(
    name="conv2d_custom_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        in_device = x.device
        w = self.conv1.weight
        b = self.conv1.bias
        if not x.is_cuda:
            x = x.cuda()
        if not w.is_cuda:
            w = w.cuda()
            b = b.cuda()
        if x.dtype != torch.float32:
            x = x.float()
        out = _conv_mod.conv2d_forward(x, w, b)
        if out.device != in_device:
            out = out.to(in_device)
        return out

